function validateImageDataUrl(value){if(typeof value!=="string"||!value)return{ok:false,reason:"missing"};const match=/^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);if(!match||match[2].length%4!==0)return{ok:false,reason:"invalid_type_or_encoding"};const padding=(match[2].endsWith("==")?2:match[2].endsWith("=")?1:0),bytes=Math.floor(match[2].length*3/4)-padding;if(bytes<=0||bytes>6*1024*1024)return{ok:false,reason:"invalid_size",bytes};return{ok:true,mime:`image/${match[1]}`,bytes}}
