function parseStructuredJson(text){let s=String(text||"").trim();if(!s)throw new Error("empty structured output");if(s.startsWith("```"))s=s.replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/i,"").trim();try{return JSON.parse(s)}catch(e){}const a=s.indexOf("{"),b=s.lastIndexOf("}");if(a>=0&&b>a)return JSON.parse(s.slice(a,b+1));throw new Error("invalid structured json")}
async function structured(env,{model,input,instructions,name,schema,max_output_tokens=1200}){const budgets=[Number(max_output_tokens)||1200,Math.min(5200,Math.max(2400,(Number(max_output_tokens)||1200)*2))];let lastErr=null,lastUsage={};for(let attempt=0;attempt<budgets.length;attempt++){const retryNote=attempt?"\nIMPORTANTE: La respuesta anterior quedó incompleta o no fue parseable. Devuelve SOLO un único objeto JSON completo que cumpla el esquema. Sé conciso; no omitas campos obligatorios.":"";const payload={model,input,instructions:String(instructions||"")+retryNote,text:{format:{type:"json_schema",name,schema,strict:true}},max_output_tokens:budgets[attempt],store:false};const r=await openai(env,"/responses",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await r.json();lastUsage=data.usage||lastUsage;const t=outputText(data);try{return{data:parseStructuredJson(t),usage:data.usage||{}}}catch(e){lastErr=e;console.error("ETERNA STRUCTURED PARSE",name,"attempt",attempt+1,"model",model,"status",data.status||"","incomplete",JSON.stringify(data.incomplete_details||null))}}throw new Error("Structured output parse failed after retry: "+name+" · "+String(lastErr&&lastErr.message||lastErr||"unknown"))}

