function legalRowAccepted(row,{minor,emailVerified}){if(!row||!emailVerified)return false;if(row.terms_accepted!==true||row.privacy_accepted!==true||row.ai_notice_accepted!==true)return false;if(!legalRelationshipValid(minor,row.relationship))return false;if(minor&&row.parental_authorization!==true)return false;return true}
async function getLegalState(env,auth,ctx=null){ctx=ctx||await getStudentContext(env,auth.user.id);const age=legalAge(ctx),minor=age==null?true:age<18,emailVerified=legalEmailVerified(auth.user),row=await getActiveLegalAcceptance(env,auth.user.id),accepted=legalRowAccepted(row,{minor,emailVerified});return{required:true,accepted,legal_version:LEGAL_VERSION,documents:LEGAL_DOCUMENTS,age,minor,email_verified:emailVerified,relationship:row?.relationship||null,accepted_at:row?.accepted_at||null,parental_authorization:Boolean(row?.parental_authorization),withdrawn:false}}
function legalRequiredResponse(state){return json({error:"ETERNA_LEGAL_ACCEPTANCE_REQUIRED",legal_version:state.legal_version,minor:state.minor,age:state.age,email_verified:state.email_verified,action:"OPEN_FAMILY_ZONE"},403)}
async function requireLegalState(env,auth,ctx=null){const state=await getLegalState(env,auth,ctx);return state.accepted?{ok:true,state}:{ok:false,state,response:legalRequiredResponse(state)}}
async function recentPurchaseAck(env,uid,plan){try{const rows=await supabase(env,`eterna_purchase_acknowledgements?user_id=eq.${encodeURIComponent(uid)}&plan=eq.${encodeURIComponent(plan)}&select=*&order=acknowledged_at.desc&limit=1`),row=rows?.[0];if(!row)return null;const age=Date.now()-new Date(row.acknowledged_at).getTime();return age>=0&&age<=30*60*1000?row:null}catch(e){return null}}
async function handleLegalConsent(request,env,auth){
  const ctx=await getStudentContext(env,auth.user.id),state=await getLegalState(env,auth,ctx);
  if(request.method==="GET")return json(state);
  const body=await request.json().catch(()=>({})),action=String(body.action||"accept");
  if(action==="purchase_ack"){
    if(!state.accepted)return legalRequiredResponse(state);
    const plan=body.plan==="annual"?"annual":"monthly";
    if(body.recurring_ack!==true||body.withdrawal_info_ack!==true||body.immediate_service_requested!==true)return json({error:"PURCHASE_ACK_INCOMPLETE"},400);
    const priceText=plan==="annual"?"79,99 € / año":"7,99 € / mes";
    await supabase(env,"eterna_purchase_acknowledgements",{method:"POST",body:{user_id:auth.user.id,legal_version:LEGAL_VERSION,plan,price_text:priceText,recurring_ack:true,withdrawal_info_ack:true,immediate_service_requested:true,acknowledged_at:new Date().toISOString()}});
    return json({ok:true,plan,price_text:priceText,acknowledged_at:new Date().toISOString()})
  }
  if(action==="withdraw"){
    const row=await getActiveLegalAcceptance(env,auth.user.id);
    if(row)await supabase(env,`eterna_legal_acceptances?id=eq.${encodeURIComponent(row.id)}`,{method:"PATCH",body:{withdrawn_at:new Date().toISOString()}});
    return json({...await getLegalState(env,auth,ctx),accepted:false,withdrawn:true})
  }
  if(!state.email_verified)return json({error:"ADULT_EMAIL_VERIFICATION_REQUIRED",legal_version:LEGAL_VERSION},409);
  const relationship=String(body.relationship||""),minor=state.minor;
  if(!legalRelationshipValid(minor,relationship))return json({error:"LEGAL_RELATIONSHIP_REQUIRED",minor},400);
  if(body.terms_accepted!==true||body.privacy_accepted!==true||body.ai_notice_accepted!==true)return json({error:"LEGAL_ACCEPTANCE_INCOMPLETE"},400);
  if(minor&&body.parental_authorization!==true)return json({error:"PARENTAL_AUTHORIZATION_REQUIRED"},400);
  const existing=await getActiveLegalAcceptance(env,auth.user.id);
  if(existing&&legalRowAccepted(existing,{minor,emailVerified:true}))return json(await getLegalState(env,auth,ctx));
  if(existing)await supabase(env,`eterna_legal_acceptances?id=eq.${encodeURIComponent(existing.id)}`,{method:"PATCH",body:{withdrawn_at:new Date().toISOString()}});
  const row={user_id:auth.user.id,legal_version:LEGAL_VERSION,user_age:state.age,relationship,adult_email:String(auth.user.email||"").slice(0,320),email_verified:true,terms_accepted:true,privacy_accepted:true,ai_notice_accepted:true,parental_authorization:minor?true:false,immediate_service_ack:false,evidence_method:"authenticated_account+confirmed_email+explicit_declaration",document_versions:LEGAL_DOCUMENTS,accepted_at:new Date().toISOString(),withdrawn_at:null};
  await supabase(env,"eterna_legal_acceptances",{method:"POST",body:row});
  return json(await getLegalState(env,auth,ctx))
}

function normalizeSubscriptionRecord(value,now=Date.now()){const s=value&&typeof value==="object"?value:null;if(!s)return{status:"inactive"};if(s.status==="trialing"){const end=Date.parse(String(s.trial_end||""));if(!Number.isFinite(end)||end<=now)return{...s,status:"expired"}}return s}
async function serverRole(env,uid){try{const rows=await supabase(env,`perfiles?id=eq.${encodeURIComponent(uid)}&select=rol`);return String(rows?.[0]?.rol||"").toLowerCase()}catch(_e){return""}}
async function serverTesterEntitlement(env,uid){try{const rows=await supabase(env,`eterna_test_entitlements?user_id=eq.${encodeURIComponent(uid)}&active=eq.true&select=active&limit=1`);return rows?.[0]?.active===true}catch(_e){return false}}
async function getSubscription(env,uid,_email){try{const [rows,role]=await Promise.all([supabase(env,`eterna_subscriptions?user_id=eq.${encodeURIComponent(uid)}&select=*`),serverRole(env,uid)]);if(role==="propietario")return{status:"active",plan:"owner"};return normalizeSubscriptionRecord(rows?.[0])}catch(e){return{status:"inactive"}}}
function subscriptionActive(s){return["active","trialing"].includes(normalizeSubscriptionRecord(s).status)}
function subscriptionUnlimited(s){const normalized=normalizeSubscriptionRecord(s);return normalized.status==="active"&&["owner","tester"].includes(String(normalized.plan||"").toLowerCase())}
const PARENT_UNLIMITED_SENTINEL=100;
function paidSubscriptionCanChooseUnlimited(s){const normalized=normalizeSubscriptionRecord(s),plan=String(normalized.plan||"").toLowerCase();return normalized.status==="active"&&["monthly","annual"].includes(plan)}
function parentUnlimitedEnabled(settings,subscription){return Number(settings&&settings.max_sessions_per_day)===PARENT_UNLIMITED_SENTINEL&&paidSubscriptionCanChooseUnlimited(subscription)}
function normalizeParentLimitRequest(value){const requestedUnlimited=String(value||"").toLowerCase()==="unlimited"||Number(value)===PARENT_UNLIMITED_SENTINEL,parsed=Number(value);return{requestedUnlimited,value:requestedUnlimited?PARENT_UNLIMITED_SENTINEL:Number.isFinite(parsed)?Math.max(1,Math.min(PARENT_UNLIMITED_SENTINEL-1,parsed)):20}}
async function getParentSettings(env,uid){try{const rows=await supabase(env,`eterna_parent_settings?user_id=eq.${encodeURIComponent(uid)}&select=*`);return rows?.[0]||{user_id:uid,voice_enabled:true,max_sessions_per_day:20,allow_image_input:true,allow_audio_input:true}}catch(e){return{user_id:uid,voice_enabled:true,max_sessions_per_day:20,allow_image_input:true,allow_audio_input:true}}}
function usageDate(env,date=new Date()){const tz=String(env.USAGE_TIMEZONE||"Europe/Madrid").trim()||"Europe/Madrid";try{const parts=new Intl.DateTimeFormat("en-US",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(date),map=Object.fromEntries(parts.filter(p=>p.type!=="literal").map(p=>[p.type,p.value]));return `${map.year}-${map.month}-${map.day}`}catch(e){return date.toISOString().slice(0,10)}}
function addUsageDays(dateString,days){const d=new Date(String(dateString)+"T12:00:00Z");d.setUTCDate(d.getUTCDate()+Number(days||0));return d.toISOString().slice(0,10)}
function usageWeekWindow(env,date=new Date()){const today=usageDate(env,date),d=new Date(today+"T12:00:00Z"),mondayIndex=(d.getUTCDay()+6)%7,start=addUsageDays(today,-mondayIndex),end=addUsageDays(start,6),next=addUsageDays(start,7);return{today,start,end,next}}
async function getTodayUsage(env,uid){const date=usageDate(env);try{const rows=await supabase(env,`eterna_usage?user_id=eq.${encodeURIComponent(uid)}&usage_date=eq.${date}&select=*`);return rows?.[0]||{user_id:uid,usage_date:date,chat_requests:0}}catch(e){return{user_id:uid,usage_date:date,chat_requests:0}}}
async function getWeekUsage(env,uid){const w=usageWeekWindow(env);try{const rows=await supabase(env,`eterna_usage?user_id=eq.${encodeURIComponent(uid)}&usage_date=gte.${w.start}&usage_date=lte.${w.end}&select=usage_date,chat_requests`),used=(rows||[]).reduce((sum,r)=>sum+Number(r.chat_requests||0),0);return{...w,used,rows:rows||[]}}catch(e){return{...w,used:0,rows:[]}}}
async function quota(env,uid,email,subscription=null){
  const [settings,usage,week,role,explicitTester]=await Promise.all([getParentSettings(env,uid),getTodayUsage(env,uid),getWeekUsage(env,uid),serverRole(env,uid),serverTesterEntitlement(env,uid)]);
  const parentDaily=Math.max(1,Math.min(100,Number(settings.max_sessions_per_day||20))),
        hardDaily=Math.max(1,Math.min(100,Number(env.MAX_CHAT_REQUESTS_PER_DAY||60))),
        dailyLimit=Math.min(parentDaily,hardDaily),
        dailyUsed=Number(usage.chat_requests||0),
        configuredWeekly=Number(env.MAX_CHAT_REQUESTS_PER_WEEK||0),
        derivedWeekly=Math.max(7,dailyLimit*7),
        weeklyLimit=configuredWeekly>0?Math.max(7,Math.min(1000,configuredWeekly)):derivedWeekly,
        weeklyUsed=Number(week.used||0);
  const tester=explicitTester||subscriptionUnlimited(subscription),parentUnlimited=parentUnlimitedEnabled(settings,subscription);
  if(role==="propietario"||tester||parentUnlimited)return{ok:true,period:null,limit:parentUnlimited?null:dailyLimit,used:dailyUsed,daily_limit:parentUnlimited?null:dailyLimit,daily_used:dailyUsed,weekly_limit:parentUnlimited?null:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,owner:role==="propietario",tester,parent_unlimited:parentUnlimited};
  if(dailyUsed>=dailyLimit)return{ok:false,period:"daily",limit:dailyLimit,used:dailyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:false};
  if(weeklyUsed>=weeklyLimit)return{ok:false,period:"weekly",limit:weeklyLimit,used:weeklyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:false};
  return{ok:true,period:null,limit:dailyLimit,used:dailyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:false}
}
async function handleAccessStatus(env,auth){
  const uid=auth.user.id,[role,explicitTester,subscription]=await Promise.all([
    serverRole(env,uid),
    serverTesterEntitlement(env,uid),
    getSubscription(env,uid,auth.user.email)
  ]);
  return json({unlimited_testing:role==="propietario"||explicitTester||subscriptionUnlimited(subscription)});
}
