function ambQ(s){const o=(s?.ambiguity_options||[]).filter(Boolean).slice(0,2);if(o.length<2)return null;const term=cleanChildText(s.ambiguity_term||s.concept||"esa palabra");if(normalizeForSearch(term)==="kiwi")return"Antes de responder, quiero asegurarme de entenderte bien. ¿Hablas del kiwi, el ave, o de la fruta kiwi?";return`Antes de responder, quiero asegurarme de entenderte bien. Cuando dices «${term}», ¿te refieres ${ambiguityOptionWithA(o[0])} o ${ambiguityOptionWithA(o[1])}?`}
function memKey(a,b){return normalizeForSearch([a,b].filter(Boolean).join("| ")).slice(0,180)}
function relMem(c,t,a,b){const q=words([t,a,b].filter(Boolean).join(" "));return(c.academicMemory||[]).map(m=>{const w=words([m.topic_label,m.resolved_meaning,m.subject,(m.key_points||[]).join(" ")].filter(Boolean).join(" "));let n=0;q.forEach(x=>{if(w.has(x))n+=2});if(a&&normalizeForSearch(m.subject||"")===normalizeForSearch(a))n+=2;return{m,n}}).filter(x=>x.n>0).sort((x,y)=>y.n-x.n).slice(0,6).map(x=>x.m)}
function prevStr(h,p){for(let i=(h||[]).length-1;i>=0;i--){const x=h[i]||{};if(x.role==="assistant"&&STRATEGIES.includes(x.strategy_used))return x.strategy_used}return STRATEGIES.includes(p?.last_strategy)?p.last_strategy:null}
function strRank(r){const e=Math.max(0,Number(r?.evidence_count||0)),c=Math.min(1,e/5),v=Math.max(.05,Math.min(.95,Number(r?.success_score==null?.5:r.success_score)));return .5*(1-c)+v*c}
