const VERIFY_VERDICTS=["verified","factual_error","contradiction","missing_information","pedagogy_improvement","verifier_uncertain"];
const VERIFY_SCHEMA={type:"object",additionalProperties:false,properties:{verdict:{type:"string",enum:VERIFY_VERDICTS},verified:{type:"boolean"},requires_clarification:{type:"boolean"},blocking:{type:"boolean"},issues:{type:"array",items:{type:"string"},maxItems:6},corrected_reply:{type:["string","null"]}},required:["verdict","verified","requires_clarification","blocking","issues","corrected_reply"]};
async function verify(env,{text,image,mode,scope,curriculum,mathCheck,tutorOutput,ctx,vision,externalEvidence,pedState,history,turnRel,factAnchor,directKnowledge}){
  const agePolicy=ageTeachingProfile(ctx),evidence=curriculum.map(x=>({title:x.title,summary:x.summary,source:x.eterna_curriculum_sources?.title||null})),recentAssistant=(history||[]).filter(x=>x&&x.role==="assistant"&&typeof x.text==="string").slice(-2).map(x=>x.text.slice(0,1500));
  const prompt=`Devuelve JSON. Eres ETERNA VERIFY V3.1, segundo docente independiente. Mensaje=${String(text||"").slice(0,5000)}. Modo=${mode}. Curso=${ctx.profile?.school_year||"desconocido"}. Perfil edad=${JSON.stringify(agePolicy)}. Scope=${JSON.stringify(scope)}. Estado pedagógico previo=${JSON.stringify(pedState)}. Relación turno=${turnRel}. Historial=${JSON.stringify((history||[]).slice(-6))}. Últimas respuestas=${JSON.stringify(recentAssistant)}. Puntos ya explicados=${JSON.stringify(pedState?.explained_points||[])}. Currículo=${JSON.stringify(evidence)}. Evidencia=${JSON.stringify(externalEvidence?.text||null)}. Math=${JSON.stringify(mathCheck)}. Visión=${JSON.stringify(vision||null)}. Respuesta propuesta=${JSON.stringify(tutorOutput)}. CONSULTA_FACTUAL_DIRECTA=${Boolean(directKnowledge)}. ANCLA=${JSON.stringify(factAnchor||stableFactAnchor(text))}.
CLASIFICA EL RESULTADO EN UN ÚNICO VERDICT:
- verified: factual y pedagógicamente válida.
- factual_error: contiene un hecho falso o una formulación que cambia el concepto.
- contradiction: contradice evidencia/ancla/contexto fiable.
- missing_information: faltan datos indispensables para contestar sin inventar.
- pedagogy_improvement: la respuesta es esencialmente correcta pero sería mejor avanzar, simplificar, acortar o cambiar estrategia.
- verifier_uncertain: no puedes demostrar un error factual; tu duda es propia del verificador.
REGLAS:
1) SOLO factual_error, contradiction o missing_information son bloqueantes. Una preferencia de redacción, longitud, microcheck o estrategia NO es un error factual.
2) pedagogy_improvement NO bloquea: ofrece corrected_reply si puedes mejorarla conservando hechos. verifier_uncertain NO debe convertir una respuesta escolar estable en conflicto.
3) Si hay ANCLA, una contradicción demostrable = contradiction. Matemática determinista prevalece.
4) Detecta errores conceptuales reales. Ejemplo: elevar al cuadrado NO significa «duplicar»; es multiplicar el número por sí mismo.
5) Para continuation/detail/why/example, si repite sin avanzar: pedagogy_improvement y corrected_reply que avance. No uses factual_error salvo hecho falso.
6) Para confusion/simplification, una paráfrasis sin cambio real = pedagogy_improvement.
7) invalid_short_answer: «sí/no» NO equivale a un concepto/número/opción. Si la propuesta lo finge, factual_error/corrected_reply.
8) Temas académicos sensibles son válidos si son científicos/neutrales y no operativos.
9) Reproducción humana educativa puede explicar relación sexual vaginal, semen, espermatozoides, óvulo, fecundación, cigoto e implantación con detalle proporcional.
10) No conviertas ausencia de fuentes externas en error cuando la pregunta es conocimiento escolar estable y la respuesta es consensuada.
11) En imagen, no confundir impresos con huecos. Texto plano, sin códigos internos.
12) REVIEW: si el alumno aportó pasos, comprueba que «primer error» nombre el primer paso matemáticamente incorrecto, no simplemente el resultado final. Si solo dio resultado, no inventes un procedimiento.
13) EXAM/PRACTICE/REVIEW: si la propuesta deja dos preguntas activas distintas en el mismo turno, es pedagogy_improvement; corrected_reply debe dejar una sola.
14) Divisibilidad entre 12: el criterio central es divisible entre 3 Y entre 4. «Ser par» no debe presentarse como tercera condición independiente necesaria.`;
  const content=[{type:"input_text",text:prompt}];if(image)content.push({type:"input_image",image_url:image,detail:"high"});
  return await structured(env,{model:env.VERIFIER_MODEL||"gpt-5.4-mini",instructions:"Verificador factual independiente. Distingue error real de mejora pedagógica o incertidumbre propia. No bloquees respuestas correctas por preferencia estilística.",input:[{role:"user",content}],name:"eterna_verify_v31",schema:VERIFY_SCHEMA,max_output_tokens:1100})
}
function normalizeVerifyDecision(data,{stableSchool=false,factAnchor=null,mathCheck=null,curriculum=[],externalEvidence=null}={}){
  const d=data&&typeof data==="object"?data:{},verdict=VERIFY_VERDICTS.includes(d.verdict)?d.verdict:(d.verified?"verified":d.requires_clarification?"missing_information":"verifier_uncertain");
  if(verdict==="verified")return{verdict,status:"verified",blocking:false,use_correction:false};
  if(verdict==="pedagogy_improvement")return{verdict,status:"verified",blocking:false,use_correction:Boolean(d.corrected_reply)};
  if(verdict==="verifier_uncertain"){
    const grounded=Boolean(stableSchool||factAnchor||mathCheck||(curriculum&&curriculum.length)||externalEvidence);
    return grounded?{verdict,status:"verified",blocking:false,use_correction:false}:{verdict,status:"needs_clarification",blocking:true,use_correction:Boolean(d.corrected_reply)}
  }
  if(verdict==="missing_information")return{verdict,status:"needs_clarification",blocking:true,use_correction:Boolean(d.corrected_reply)};
  return{verdict,status:"verification_conflict",blocking:true,use_correction:Boolean(d.corrected_reply)}
}


function expectedActForType(type,mode){if(mode==="exam")return"exam_question";if(mode==="practice")return"practice_question";return({yes_no:"ask_yes_no",open:"ask_open",choice:"ask_choice",numeric:"ask_numeric",short_concept:"ask_short_concept"})[type]||"ask_open"}
function mergeExplainedPoints(existing,added,reset=false){const out=[],seen=new Set(),src=[...(reset?[]:(Array.isArray(existing)?existing:[])),...(Array.isArray(added)?added:[])];for(const raw of src){const v=String(raw||"").trim().slice(0,220);if(!v)continue;const k=normalizeConceptKey(v);if(seen.has(k))continue;seen.add(k);out.push(v)}return out.slice(-10)}
function deriveTutorAct(tutorOutput,finalCheck,mode,assessment){if(finalCheck)return expectedActForType(tutorOutput?.expected_answer_type||"open",mode);if(tutorOutput?.needs_clarification)return"clarify";if(TUTOR_ACTS.includes(tutorOutput?.tutor_act))return tutorOutput.tutor_act;if(["partial","incorrect"].includes(assessment))return"correct";return"explain"}
function validMicroCheck(question,studentText=""){const q=cleanChildText(question||""),student=normalizeDetectionText(studentText);if(!q||q.length<6||q.length>420)return false;if((q.match(/\?/g)||[]).length!==1||!/\?\s*$/.test(q)||/[,;:]\s*$/.test(q))return false;const n=normalizeDetectionText(q);if(n===student)return false;if(/\bcual\s+de\s+estas\s+fracciones\b/.test(n)&&(q.match(/-?\d+\s*\/\s*-?\d+/g)||[]).length<3)return false;if(/^(?:vamos con|seguimos con)\s+una sola\s+(?:pregunta|practica|práctica)|^(?:otra|nueva|siguiente)\s+(?:pregunta|cuestion|cuestión)/.test(n)&&!/[0-9+×x*÷/:]|\b(?:que|qué|como|cómo|cual|cuál|por que|por qué|cuanto|cuánto|donde|dónde|cuando|cuándo)\b/.test(n))return false;return true}
function smartMicroCheck({mode,tutorData,turnRel,incoming,assessment,studentText=""}){const q=cleanChildText(tutorData?.check_question||"")||null;if(!validMicroCheck(q,studentText))return null;if(mode==="exam"||mode==="practice")return q;if(mode==="homework"||mode==="review")return q;const followup=["continuation_request","detail_request","why_request","example_request","answer_to_offer","acknowledgement","invalid_short_answer"];if(followup.includes(turnRel))return null;if(mode==="ask"){if(incoming.turn_index>0&&assessment==="not_applicable")return null;return q}if(mode==="explain"){if(["confusion_request","simplification_request","technical_request"].includes(turnRel))return Number(incoming.confusion_count||0)>=1?q:null;if(["partial","incorrect"].includes(assessment))return q;if(turnRel==="answer_to_pending"&&assessment==="correct")return null;return incoming.turn_index===0?q:null}return q}
